sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }

    // Se o novo valor for igual ao antigo, ignora para evitar loop
    if (newValue === oldValue) {
        return;
    }

    var ga = new GlideAjax('x_fub_fundbrad_ev.EVUtils');
    ga.addParam('sysparm_name', 'formatPhoneNumber');
    ga.addParam('sysparm_telefone', newValue);

    ga.getXMLAnswer(function (response) {
        if (!response) {
            return;
        }

        var phoneResult = JSON.parse(response);

        if (phoneResult.isValid) {
            // Evita redefinir se o campo já estiver com o valor formatado correto
            if (g_form.getValue('u_telefone_solicitante') !== phoneResult.formattedPhone) {
                g_form.setValue('u_telefone_solicitante', phoneResult.formattedPhone);
            }
            g_form.hideFieldMsg('u_telefone_solicitante', true);
        } else {
            g_form.setValue('u_telefone_solicitante', '');

            getMessage('telefone_invalido_msg', function (msg) {
                var finalMessage = msg.replace('{0}', newValue);
                g_form.showFieldMsg('u_telefone_solicitante', finalMessage, 'error', true);
            });
        }
    });
}
